<script setup>
import axios from "axios";
import { computed, onMounted, reactive, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import Layout from "../../../layouts/main.vue";
import LoadingState from "../../../components/ui/loading-state.vue";
import RiskLevelBadge from "../../../components/risk-prevention/iper/RiskLevelBadge.vue";
import RiskMatrixGrid from "../../../components/risk-prevention/iper/RiskMatrixGrid.vue";
import RiskApprovalPanel from "../../../components/risk-prevention/iper/RiskApprovalPanel.vue";
import RiskValidationSummary from "../../../components/risk-prevention/iper/RiskValidationSummary.vue";
import RiskVersionComparison from "../../../components/risk-prevention/iper/RiskVersionComparison.vue";
import { downloadRiskMatrixPdf } from "../../../components/risk-prevention/iper/risk-matrix-pdf";
import { riskMatrixApi, toEditableStructure } from "../../../services/risk-matrix-api";
import { downloadRiskFile, formatRiskDate, formatRiskError, showRiskError, showRiskSuccess } from "../../../components/risk-prevention/module-utils";

const route = useRoute(); const router = useRouter();
const loading = ref(true); const busy = ref(false); const version = ref(null); const versions = ref([]); const catalogs = ref({ catalogs:{}, users:[], permissions:[] }); const validation = ref({ data:[] }); const comparison = ref(null); const audit = ref([]);
const tab = ref(route.query.tab || "summary");
const addingParticipant = ref(false);
const participant = reactive({ participant_user_id:null, participant_name_snapshot:"", participant_role:"", representation_type:"worker", participation_date:new Date().toISOString().slice(0,10), comments:"", response_or_resolution:"", acknowledged:false });
const tabs = [["summary","Resumen","bx-grid-alt"],["general","Datos generales","bx-building"],["matrix","Matriz de riesgos","bx-table"],["controls","Controles","bx-shield"],["program","Programa preventivo","bx-task"],["evidence","Evidencias","bx-paperclip"],["participation","Participación","bx-group"],["versions","Versiones","bx-history"],["approvals","Aprobaciones","bx-badge-check"],["audit","Auditoría","bx-fingerprint"]];
const risks = computed(() => version.value?.processes?.flatMap((p) => p.tasks?.flatMap((t) => t.risks || []) || []) || []);
const controls = computed(() => risks.value.flatMap((risk) => (risk.controls || []).map((control) => ({ ...control, risk_name: risk.specific_risk_name }))));
const status = computed(() => typeof version.value?.status === "string" ? version.value.status : version.value?.status?.value);
function currentAssessment(risk) { return risk.current_assessment || (risk.assessments || []).find((item) => item.phase === "current" && item.active !== false) || {}; }
async function load() { loading.value = true; try { catalogs.value = await riskMatrixApi.catalogs(); versions.value = await riskMatrixApi.versions(route.params.id); const selected = Number(route.query.version || versions.value[0]?.id); version.value = await riskMatrixApi.version(selected); validation.value = await riskMatrixApi.validation(selected); if (catalogs.value.permissions.includes("risk-matrix.view-audit") || catalogs.value.permissions.includes("__superadmin__")) { const { data } = await axios.get(`/api/risk-prevention/risk-matrices/${route.params.id}/audit`); audit.value = data.data || []; } } catch(error){ showRiskError(formatRiskError(error,"No se pudo cargar la matriz.")); } finally{ loading.value=false; } }
async function chooseVersion(id){ await router.replace({ query:{ ...route.query, version:id } }); version.value=await riskMatrixApi.version(id); validation.value=await riskMatrixApi.validation(id); comparison.value=null; }
async function workflow(action,payload){ busy.value=true; try{const response=await riskMatrixApi.workflow(version.value.id,action,payload);showRiskSuccess(response.message);await load();}catch(error){showRiskError(formatRiskError(error,"No se pudo completar la transición."));}finally{busy.value=false;} }
async function createVersion(){ const reason=window.prompt("Motivo de la nueva versión:"); if(!reason)return; try{const response=await riskMatrixApi.createVersion(route.params.id,{source_version_id:version.value.id,reason});showRiskSuccess(response.message);router.push(`/risk-prevention/matrices/${route.params.id}/editar?version=${response.data.id}`);}catch(error){showRiskError(formatRiskError(error));} }
async function compareTo(id){ if(!id)return comparison.value=null; comparison.value=await riskMatrixApi.compare(version.value.id,id); }
async function exportXlsx(historical=false){ try{await downloadRiskFile(`/api/risk-prevention/risk-matrix-versions/${version.value.id}/export/xlsx${historical?'?format=historical':''}`,`${version.value.matrix.code}-v${version.value.version_number}.xlsx`);}catch(error){showRiskError(formatRiskError(error,"No se pudo exportar."));} }
function participantUserChanged(){ const selected=catalogs.value.users.find((item)=>item.id===Number(participant.participant_user_id)); if(selected)participant.participant_name_snapshot=selected.name; }
async function addParticipant(){ busy.value=true; try{await riskMatrixApi.addParticipation(version.value.id,participant);showRiskSuccess("Participación registrada con trazabilidad.");addingParticipant.value=false;Object.assign(participant,{participant_user_id:null,participant_name_snapshot:"",participant_role:"",representation_type:"worker",participation_date:new Date().toISOString().slice(0,10),comments:"",response_or_resolution:"",acknowledged:false});await load();}catch(error){showRiskError(formatRiskError(error,"No se pudo registrar la participación."));}finally{busy.value=false;} }
async function removeParticipant(id){ if(!window.confirm("¿Eliminar esta constancia de la versión editable?"))return;try{await riskMatrixApi.deleteParticipation(id);showRiskSuccess("Constancia eliminada.");await load();}catch(error){showRiskError(formatRiskError(error));} }
onMounted(load);
</script>

<template>
  <Layout><LoadingState v-if="loading" message="Reconstruyendo versión y trazabilidad…" /><template v-else-if="version">
    <div class="detail-hero"><div><router-link to="/risk-prevention/matrices"><i class="bx bx-left-arrow-alt"></i> Matrices IPER/MIPER</router-link><span>{{ version.matrix.code }} · v{{ version.version_number }}</span><h2>{{ version.matrix.name }}</h2><p>{{ version.company_name_snapshot }} · {{ version.work_center_name_snapshot || 'Centro institucional' }}</p></div><div class="hero-buttons"><button class="btn btn-outline-light" @click="exportXlsx(false)"><i class="bx bx-spreadsheet"></i> Excel moderno</button><button class="btn btn-outline-light" @click="exportXlsx(true)">Excel histórico</button><button class="btn btn-light" @click="downloadRiskMatrixPdf(version)"><i class="bx bxs-file-pdf"></i> PDF ejecutivo</button></div><div class="detail-status"><span>{{ status }}</span><strong>{{ risks.length }}</strong><small>riesgos evaluados</small></div></div>
    <div class="detail-kpis"><article><span>Estado</span><strong>{{ status }}</strong></article><article><span>Fecha de aprobación</span><strong>{{ formatRiskDate(version.approved_at) }}</strong></article><article><span>Próxima revisión</span><strong>{{ formatRiskDate(version.next_review_at) }}</strong></article><article><span>Importantes</span><strong>{{ risks.filter((r)=>Number(currentAssessment(r).calculated_score)===8).length }}</strong></article><article><span>Intolerables</span><strong>{{ risks.filter((r)=>Number(currentAssessment(r).calculated_score)===16).length }}</strong></article><article><span>Programa</span><strong>{{ version.program?.progress_percentage || 0 }}%</strong></article></div>
    <nav class="detail-tabs"><button v-for="item in tabs" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]"><i class="bx" :class="item[2]"></i>{{ item[1] }}</button></nav>
    <section class="detail-panel">
      <template v-if="tab==='summary'"><div class="summary-grid"><RiskValidationSummary :issues="validation.data" /><article class="method-card"><span>Metodología vigente de la versión</span><h5>{{ version.methodology.name }}</h5><strong>{{ version.methodology.code }} · v{{ version.methodology.version_number }}</strong><p>Los valores calculados provienen del backend y del catálogo versionado.</p></article></div><div class="risk-level-list"><article v-for="risk in risks" :key="risk.id"><div><span>{{ risk.family?.name }}</span><strong>{{ risk.specific_risk_name }}</strong><small>{{ risk.possible_harm }}</small></div><RiskLevelBadge :level="currentAssessment(risk).calculated_level" :score="currentAssessment(risk).calculated_score" /></article></div></template>
      <template v-else-if="tab==='general'"><div class="data-grid"><div v-for="item in [['Empresa',version.company_name_snapshot],['RUT',version.company_tax_id_snapshot],['Dirección',version.company_address_snapshot],['Centro',version.work_center_name_snapshot],['Fecha elaboración',formatRiskDate(version.prepared_on)],['Personas trabajadoras',version.total_workers],['Responsable',version.program_responsible_name_snapshot],['Representante legal',version.legal_representative_name_snapshot],['Motivo revisión',version.review_reason],['Hash',version.snapshot_hash]]" :key="item[0]"><span>{{ item[0] }}</span><strong>{{ item[1] || '—' }}</strong></div></div></template>
      <RiskMatrixGrid v-else-if="tab==='matrix'" :model-value="toEditableStructure(version)" :catalogs="catalogs.catalogs" :users="catalogs.users" readonly />
      <template v-else-if="tab==='controls'"><div class="table-responsive"><table class="table control-table"><thead><tr><th>Riesgo</th><th>Etapa</th><th>Jerarquía</th><th>Medida</th><th>Responsable</th><th>Plazo</th><th>Estado</th><th>Avance</th></tr></thead><tbody><tr v-for="control in controls" :key="control.id"><td>{{ control.risk_name }}</td><td>{{ control.control_stage }}</td><td>{{ control.hierarchy_type }}</td><td>{{ control.description }}</td><td>{{ control.responsible?.name || control.responsible_text || '—' }}</td><td>{{ formatRiskDate(control.due_date) }}</td><td>{{ control.status }}</td><td>{{ control.progress_percentage }}%</td></tr></tbody></table></div></template>
      <template v-else-if="tab==='program'"><div v-if="version.program" class="program-head"><div><span>{{ version.program.code }}</span><h5>{{ version.program.name }}</h5></div><strong>{{ version.program.progress_percentage }}%</strong></div><div class="program-actions"><article v-for="action in version.program?.actions || []" :key="action.id"><div><span>{{ action.hierarchy_type }}</span><strong>{{ action.action_description }}</strong><small>{{ action.responsible?.name || 'Sin asignar' }} · vence {{ formatRiskDate(action.due_date) }}</small></div><span class="action-status">{{ action.status }} · {{ action.progress_percentage }}%</span></article><p v-if="!version.program">El programa se genera al aprobar la matriz.</p></div></template>
      <template v-else-if="tab==='evidence'"><div class="evidence-list"><article v-for="item in version.evidences" :key="item.id"><i class="bx bx-file"></i><div><strong>{{ item.original_name }}</strong><span>{{ item.evidence_type }} · {{ formatRiskDate(item.evidence_date) }} · {{ Math.round(item.file_size/1024) }} KB</span></div><button class="btn btn-sm btn-light" @click="downloadRiskFile(`/api/risk-prevention/risk-evidences/${item.id}/download`,item.original_name)"><i class="bx bx-download"></i></button></article><p v-if="!version.evidences?.length">Sin evidencias cargadas.</p></div></template>
      <template v-else-if="tab==='participation'"><div class="participation-head"><div><h5>Participación y consulta</h5><p>Constancias nominales vinculadas a esta versión.</p></div><button v-if="['draft','observed','in_review'].includes(status)" class="btn btn-primary btn-sm" @click="addingParticipant=true"><i class="bx bx-user-plus"></i> Registrar participante</button></div><div class="participation-list"><article v-for="item in version.participations" :key="item.id"><i class="bx bx-user-voice"></i><div><strong>{{ item.participant_name_snapshot }}</strong><span>{{ item.representation_type }} · {{ formatRiskDate(item.participation_date) }} · {{ item.participant_role || 'Participante' }}</span><p>{{ item.comments }}</p><small v-if="item.response_or_resolution">Respuesta: {{ item.response_or_resolution }}</small></div><button v-if="['draft','observed'].includes(status)" class="btn btn-sm btn-light text-danger" @click="removeParticipant(item.id)"><i class="bx bx-trash"></i></button></article><p v-if="!version.participations?.length">Aún no se han registrado constancias de participación.</p></div></template>
      <template v-else-if="tab==='versions'"><div class="version-tools"><select class="form-select" @change="compareTo($event.target.value)"><option value="">Comparar la versión actual con…</option><option v-for="item in versions.filter((v)=>v.id!==version.id)" :key="item.id" :value="item.id">v{{ item.version_number }} · {{ item.status }}</option></select><button v-if="['approved','superseded'].includes(status)" class="btn btn-primary" @click="createVersion"><i class="bx bx-git-branch"></i> Crear nueva versión</button></div><RiskVersionComparison v-if="comparison" :comparison="comparison" /><div class="timeline"><button v-for="item in versions" :key="item.id" :class="{active:item.id===version.id}" @click="chooseVersion(item.id)"><i class="bx bx-history"></i><span>Versión {{ item.version_number }}</span><strong>{{ item.status }}</strong><small>{{ formatRiskDate(item.approved_at || item.created_at) }}</small></button></div></template>
      <RiskApprovalPanel v-else-if="tab==='approvals'" :version="version" :permissions="catalogs.permissions" :busy="busy" @action="workflow" />
      <template v-else-if="tab==='audit'"><div class="audit-list"><article v-for="item in audit" :key="item.id"><i class="bx bx-fingerprint"></i><div><strong>{{ item.action }}</strong><span>{{ item.user?.name || 'Sistema' }} · {{ new Date(item.created_at).toLocaleString('es-CL') }}</span><p>{{ item.reason }}</p></div></article><p v-if="!audit.length">Sin eventos visibles o sin permiso de auditoría.</p></div></template>
    </section>
    <div v-if="['draft','observed'].includes(status)" class="edit-fab"><button class="btn btn-primary" @click="router.push(`/risk-prevention/matrices/${version.matrix.id}/editar?version=${version.id}`)"><i class="bx bx-edit"></i> Continuar edición</button></div>
    <div v-if="addingParticipant" class="participant-backdrop" @click.self="addingParticipant=false"><form class="participant-modal" @submit.prevent="addParticipant"><header><div><span>Consulta y participación</span><h5>Nueva constancia</h5></div><button type="button" @click="addingParticipant=false"><i class="bx bx-x"></i></button></header><div class="participant-fields"><label><span>Persona vinculada (opcional)</span><select v-model="participant.participant_user_id" class="form-select" @change="participantUserChanged"><option :value="null">Registro externo o manual</option><option v-for="user in catalogs.users" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label><span>Nombre de la persona *</span><input v-model="participant.participant_name_snapshot" required class="form-control"></label><label><span>Representación *</span><select v-model="participant.representation_type" required class="form-select"><option v-for="item in catalogs.catalogs.representation_type || []" :key="item.code" :value="item.code">{{ item.name }}</option></select></label><label><span>Fecha *</span><input v-model="participant.participation_date" required type="date" class="form-control"></label><label class="full"><span>Rol o calidad</span><input v-model="participant.participant_role" class="form-control" placeholder="Ej.: representante de trabajadores"></label><label class="full"><span>Observaciones</span><textarea v-model="participant.comments" class="form-control" rows="3"></textarea></label><label class="full"><span>Respuesta o resolución</span><textarea v-model="participant.response_or_resolution" class="form-control" rows="2"></textarea></label><label class="check full"><input v-model="participant.acknowledged" type="checkbox"><span>La persona tomó conocimiento de la matriz y sus medidas</span></label></div><footer><button type="button" class="btn btn-light" @click="addingParticipant=false">Cancelar</button><button class="btn btn-primary" :disabled="busy"><i class="bx bx-check-circle"></i> Guardar constancia</button></footer></form></div>
  </template></Layout>
</template>

<style scoped>
.detail-hero{position:relative;display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;padding:1.2rem 1.35rem;border-radius:14px;background:linear-gradient(125deg,#132f4c,#16737a);color:#fff}.detail-hero a,.detail-hero>div>span{display:block;color:#c6e0e3;font-size:.6rem}.detail-hero h2{margin:.15rem 0}.detail-hero p{margin:0;color:#d5e8ea;font-size:.7rem}.hero-buttons{display:flex;gap:.4rem}.hero-buttons .btn{display:inline-flex;align-items:center;gap:.3rem;white-space:nowrap}.detail-status{text-align:right}.detail-status>span{display:inline-flex;padding:.22rem .4rem;border-radius:99px;background:rgba(255,255,255,.14);font-size:.58rem;text-transform:uppercase}.detail-status strong,.detail-status small{display:block}.detail-status strong{font-size:1.5rem}.detail-status small{color:#c6e0e3;font-size:.58rem}.detail-kpis{display:grid;grid-template-columns:repeat(6,1fr);margin-top:.7rem;border:1px solid #e1e7ee;border-radius:10px;background:#fff}.detail-kpis article{padding:.65rem .75rem;border-right:1px solid #e1e7ee}.detail-kpis article:last-child{border:0}.detail-kpis span,.detail-kpis strong{display:block}.detail-kpis span{color:#667085;font-size:.56rem}.detail-kpis strong{font-size:.78rem}.detail-tabs{display:flex;overflow:auto;margin-top:.7rem;border:1px solid #e1e7ee;border-radius:9px;background:#fff}.detail-tabs button{display:flex;align-items:center;gap:.3rem;padding:.62rem .7rem;border:0;border-right:1px solid #edf0f3;background:#fff;color:#667085;font-size:.61rem;white-space:nowrap}.detail-tabs .active{background:#eaf5f5;color:#176b76;font-weight:750}.detail-panel{min-height:430px;margin-top:.7rem;padding:.9rem;border:1px solid #e1e7ee;border-radius:11px;background:#fff}.summary-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:.7rem}.method-card{padding:1rem;border:1px solid #dce7eb;border-radius:10px;background:#f4faf9}.method-card span,.method-card strong{display:block}.method-card span{color:#667085;font-size:.58rem}.method-card h5{margin:.2rem 0}.method-card strong{color:#176b76;font-size:.7rem}.method-card p{margin:.5rem 0 0;color:#667085;font-size:.64rem}.risk-level-list{display:grid;grid-template-columns:1fr 1fr;gap:.4rem;margin-top:.7rem}.risk-level-list article{display:flex;align-items:center;justify-content:space-between;gap:.6rem;padding:.55rem .65rem;border:1px solid #e6ebf0;border-radius:8px}.risk-level-list span,.risk-level-list strong,.risk-level-list small{display:block}.risk-level-list span,.risk-level-list small{color:#667085;font-size:.56rem}.risk-level-list strong{font-size:.69rem}.data-grid{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #e1e7ee}.data-grid div{min-height:70px;padding:.7rem;border-right:1px solid #e1e7ee;border-bottom:1px solid #e1e7ee}.data-grid span,.data-grid strong{display:block}.data-grid span{color:#667085;font-size:.57rem}.data-grid strong{margin-top:.2rem;font-size:.7rem;overflow-wrap:anywhere}.control-table{font-size:.66rem}.control-table th{background:#f7f9fb;color:#536174}.program-head{display:flex;align-items:center;justify-content:space-between;padding:.8rem;border-radius:9px;background:#eef7f5}.program-head span{color:#667085;font-size:.58rem}.program-head h5{margin:.1rem 0}.program-head>strong{color:#15803d;font-size:1.2rem}.program-actions{display:grid;gap:.4rem;margin-top:.6rem}.program-actions article,.evidence-list article,.participation-list article,.audit-list article{display:flex;align-items:center;justify-content:space-between;gap:.7rem;padding:.6rem;border:1px solid #e4e9ef;border-radius:8px}.program-actions span,.program-actions strong,.program-actions small,.evidence-list strong,.evidence-list span,.participation-list strong,.participation-list span,.audit-list strong,.audit-list span{display:block}.program-actions span,.program-actions small,.evidence-list span,.participation-list span,.audit-list span{color:#667085;font-size:.58rem}.action-status{white-space:nowrap}.evidence-list,.participation-list,.audit-list{display:grid;gap:.4rem}.evidence-list article>i,.participation-list article>i,.audit-list article>i{color:#176b76;font-size:1.25rem}.evidence-list article>div,.participation-list article>div,.audit-list article>div{flex:1}.participation-list p,.audit-list p{margin:.2rem 0 0;color:#536174;font-size:.63rem}.version-tools{display:flex;gap:.5rem;margin-bottom:.7rem}.version-tools .form-select{max-width:380px}.timeline{display:flex;overflow:auto;gap:.45rem;margin-top:.7rem}.timeline button{min-width:150px;padding:.6rem;border:1px solid #dce3eb;border-radius:8px;background:#fff;text-align:left}.timeline .active{border-color:#176b76;background:#f0f8f7}.timeline span,.timeline strong,.timeline small{display:block}.timeline span,.timeline small{color:#667085;font-size:.56rem}.timeline strong{font-size:.66rem}.edit-fab{position:fixed;z-index:20;right:1.2rem;bottom:1.2rem}.edit-fab .btn{box-shadow:0 10px 24px rgba(23,107,118,.24)}@media(max-width:1000px){.detail-hero{align-items:flex-start;flex-direction:column}.hero-buttons{width:100%;overflow:auto}.detail-status{position:absolute;right:1rem;top:1rem}.detail-kpis{grid-template-columns:repeat(3,1fr)}.summary-grid{grid-template-columns:1fr}}@media(max-width:650px){.detail-kpis,.data-grid,.risk-level-list{grid-template-columns:1fr 1fr}.detail-panel{padding:.55rem}.detail-status{display:none}}
.participation-head{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.65rem}.participation-head h5,.participation-head p{margin:0}.participation-head p{color:#667085;font-size:.62rem}.participant-backdrop{position:fixed;z-index:1060;inset:0;display:grid;place-items:center;padding:1rem;background:rgba(17,35,52,.58);backdrop-filter:blur(3px)}.participant-modal{width:min(680px,100%);overflow:hidden;border-radius:14px;background:#fff;box-shadow:0 24px 80px rgba(15,31,46,.32)}.participant-modal header,.participant-modal footer{display:flex;align-items:center;justify-content:space-between;padding:.85rem 1rem}.participant-modal header{border-bottom:1px solid #e5eaf0;background:linear-gradient(120deg,#f4faf9,#fff)}.participant-modal header span{color:#176b76;font-size:.58rem;font-weight:750;text-transform:uppercase}.participant-modal header h5{margin:.1rem 0}.participant-modal header button{border:0;background:transparent;font-size:1.4rem}.participant-modal footer{justify-content:flex-end;gap:.45rem;border-top:1px solid #e5eaf0}.participant-fields{display:grid;grid-template-columns:1fr 1fr;gap:.65rem;padding:1rem}.participant-fields label>span{display:block;margin-bottom:.22rem;color:#526170;font-size:.61rem;font-weight:700}.participant-fields .full{grid-column:1/-1}.participant-fields .check{display:flex;align-items:center;gap:.45rem}.participant-fields .check span{margin:0}.participant-fields .form-control,.participant-fields .form-select{font-size:.68rem}@media(max-width:650px){.participant-fields{grid-template-columns:1fr}.participant-fields .full{grid-column:auto}}
</style>
